mapper.select:
SELECT p.project_name AS projectName, p.project_content_desc AS projectDesc, p.path AS projectPath, e.experiment_name AS experimentName, e.path AS experimentPath, d.data_name AS dataName, d.data_type AS dataType, d.storage_file_id AS storageFileId FROM SYSTEM_COLLABORATION_TEST.md_data_relation d INNER JOIN SYSTEM_COLLABORATION_TEST.d_experiment_info e ON d.experiment_id = e.experiment_id INNER JOIN SYSTEM_COLLABORATION_TEST.d_project_info p ON e.project_id = p.project_id
AND p.project_name = #{projectName}
AND e.experiment_name = #{experiementName}
AND date_format(e.start_time,'%Y-%m-%d') = date_format(#{startTime},'%Y-%m-%d')
ORDER BY d.id ASC
